20	/**
21	 * Single source of truth for the fixed, lookup-based postcode rule: a 4-digit postcode, when
22	 * present, must fall within the inclusive range of the region derived from the owner's city.
23	 *
24	 * <p>The region is looked up from the owner's city via {@link CityRegions}, the shared city-to-region
25	 * table; each region owns an inclusive 4-digit range ({@code NSW 2000-2099, VIC 3000-3099,
26	 * QLD 4000-4099}). A city with no known region accepts any 4-digit postcode. Postcode is optional:
27	 * an absent value is always accepted. Four-digit formatting is enforced separately by the
28	 * {@code @Pattern} constraint on the inbound DTO, so this only decides whether a present,
29	 * well-formed postcode is in range for its city.
30	 */
31	public final class PostcodeRules {
32	
33	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
34	        "NSW", new int[] {2000, 2099},
35	        "VIC", new int[] {3000, 3099},
36	        "QLD", new int[] {4000, 4099});
37	
38	    private PostcodeRules() {
39	    }
40	
41	    /**
42	     * Decide whether {@code postcode} is acceptable for {@code city}.
43	     *
44	     * @param city     the owner's city (may be {@code null})
45	     * @param postcode the inbound postcode (may be {@code null})
46	     * @return {@code true} when the postcode is absent, is not a 4-digit value (left to
47	     * {@code @Pattern}), the city has no known region, or the postcode is within the city's region
48	     * range; {@code false} only when a 4-digit postcode is out of range for the city's known region
49	     */
50	    public static boolean isValidForCity(String city, String postcode) {
51	        if (postcode == null || !postcode.matches("\\d{4}")) {
52	            return true;
53	        }
54	        String region = CityRegions.regionOf(city);
55	        if (region == null) {
56	            return true;
57	        }
58	        int[] range = REGION_POSTCODES.get(region);
59	        int value = Integer.parseInt(postcode);
60	        return value >= range[0] && value <= range[1];
61	    }
62	}
