16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "membership_number")
66	    private String membershipNumber;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "bulk_signup_warning")
75	    private boolean bulkSignupWarning;
76	
77	    @Column(name = "household_member_count")
78	    private Integer householdMemberCount;
79	
80	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
81	    private Set<Pet> pets;
82	
83	    /**
84	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
85	     * another owner already shares the same last name and address. Never persisted or returned.
86	     */
87	    @Transient
88	    private boolean sharesHousehold;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getPostcode() {
107	        return this.postcode;
108	    }
109	
110	    public void setPostcode(String postcode) {
111	        this.postcode = postcode;
112	    }
113	
114	    public String getTelephone() {
115	        return this.telephone;
116	    }
117	
118	    public void setTelephone(String telephone) {
119	        this.telephone = telephone;
120	    }
121	
122	    public String getEmail() {
123	        return this.email;
124	    }
125	
126	    public void setEmail(String email) {
127	        this.email = email;
128	    }
129	
130	    public LocalDate getRegistrationDate() {
131	        return this.registrationDate;
132	    }
133	
134	    public void setRegistrationDate(LocalDate registrationDate) {
135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public String getCustomerCode() {
139	        return this.customerCode;
140	    }
141	
142	    public void setCustomerCode(String customerCode) {
143	        this.customerCode = customerCode;
144	    }
145	
146	    public String getMembershipNumber() {
147	        return this.membershipNumber;
148	    }
149	
150	    public void setMembershipNumber(String membershipNumber) {
151	        this.membershipNumber = membershipNumber;
152	    }
153	
154	    public String getHouseholdId() {
155	        return this.householdId;
156	    }
157	
158	    public void setHouseholdId(String householdId) {
159	        this.householdId = householdId;
160	    }
161	
162	    public Integer getNamesakeCount() {
163	        return this.namesakeCount;
164	    }
165	
166	    public void setNamesakeCount(Integer namesakeCount) {
167	        this.namesakeCount = namesakeCount;
168	    }
169	
170	    /**
171	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 3, assigned at creation: it
172	     * starts at 1, gains 1 when an email is present, gains 1 when the owner's name was unique at
173	     * creation time ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
174	     */
175	    @Transient
176	    public Integer getMembershipLevel() {
177	        int level = 1;
178	        if (this.email != null && !this.email.isBlank()) {
179	            level++;
180	        }
181	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
182	            level++;
183	        }
184	        return Math.min(level, 3);
185	    }
186	
187	    /**
188	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
189	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
190	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
191	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
192	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
193	     */
194	    @Transient
195	    public String getIdentityKey() {
196	        String telephonePart = this.telephone == null ? "" : this.telephone;
197	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
198	        String householdPart = this.householdId == null ? "" : this.householdId;
199	        return telephonePart + "|" + emailPart + "|" + householdPart;
200	    }
201	
202	    public boolean isBulkSignupWarning() {
203	        return this.bulkSignupWarning;
204	    }
205	
206	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
207	        this.bulkSignupWarning = bulkSignupWarning;
208	    }
209	
210	    public Integer getHouseholdMemberCount() {
211	        return this.householdMemberCount;
212	    }
213	
214	    public void setHouseholdMemberCount(Integer householdMemberCount) {
215	        this.householdMemberCount = householdMemberCount;
216	    }
217	
218	    public boolean isSharesHousehold() {
219	        return this.sharesHousehold;
220	    }
